<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { IconCheck, IconCloud, IconFile, IconTranslate, IconUpload } from "@arco-design/web-vue/es/icon";

type ThemeName = "green" | "gold" | "purple";
type Language = "zh" | "en";

const themes: Record<ThemeName, { label: string; color: string; hover: string; pressed: string }> = {
  green: { label: "绿色", color: "#16865f", hover: "#2a9d76", pressed: "#0f6848" },
  gold: { label: "金色", color: "#b8771e", hover: "#ca8c35", pressed: "#8e5b12" },
  purple: { label: "紫色", color: "#7046b6", hover: "#855fc3", pressed: "#57358f" },
};

const language = ref<Language>((localStorage.getItem("co-scientist-language") as Language) || "zh");
const themeName = ref<ThemeName>((localStorage.getItem("co-scientist-theme") as ThemeName) || "green");
const catalog = ref<any>({});
const monitor = ref<any>({});
const history = ref<any[]>([]);
const directActivationAllowed = ref(false);
const selectedFile = ref<File | null>(null);
const dryRun = ref(false);
const inputKey = ref(0);
const loading = ref(true);
const uploading = ref(false);
const error = ref("");
const result = ref<any>(null);

const currentTheme = computed(() => themes[themeName.value]);
const themeStyles = computed(() => ({
  "--theme-color": currentTheme.value.color,
  "--theme-color-hover": currentTheme.value.hover,
  "--theme-color-pressed": currentTheme.value.pressed,
  "--theme-soft": `${currentTheme.value.color}12`,
}));
const isEnglish = computed(() => language.value === "en");
const pendingReviewCount = computed(() => Number(monitor.value?.pending_count || 0));
const copy = computed(() => isEnglish.value ? {
  knowledge: "Knowledge Base", sessions: "Research Sessions", newSession: "New session", theme: "Theme", back: "Breeding sessions",
  kicker: "KNOWLEDGE INTAKE CENTER", title: "Knowledge intake center", lead: "Upload a new breeding knowledge batch. The system validates, deduplicates and merges it before expert review.",
  catalog: "Active knowledge base", healthy: "Knowledge base ready", notReady: "Not established", latest: "Latest update", preserved: "Existing knowledge remains available to new sessions.", review: "Review queue", noReview: "No batches waiting for review", reviewHint: "Uploaded batches are checked first and enter the knowledge base after approval.",
  uploadKicker: "UPLOAD A BATCH", uploadTitle: "Upload a knowledge ZIP", uploadLead: "Use the standard package format so every record can be traced, validated and merged safely.", choose: "Choose a knowledge batch", drop: "Drop a .zip file here or browse", onlyZip: "ZIP only · at least one valid data category is required", preflight: "Preflight only; do not activate directly", reviewFirst: "Upload enters expert review before activation", upload: "Upload and preflight", uploading: "Processing…", template: "Download standard template", demo: "Download demo batch", firstUse: "First time? Start with the demo batch to experience the full preflight and review flow.", safety: "Existing knowledge is never overwritten by a failed preflight or rejected review.",
  packageKicker: "PACKAGE CONTENTS", packageTitle: "What belongs in the ZIP?", packageLead: "Each category adds a different layer of breeding evidence. Upload one or several categories in a batch.", germplasm: "Germplasm resources", graph: "Crop knowledge graph", evidence: "Evidence documents", marker: "Marker / QTL", phenotype: "Phenotype protocols", trial: "Field trials", formatTitle: "Format guidance", format1: "Prefer the downloaded template. Use .md or .txt for literature and experiment notes.", format2: "Missing categories can be omitted; the importer preserves the existing knowledge base.", format3: "A ZIP with no valid records is rejected before any knowledge update.", workflow: "What happens after upload?", safe: "Safe extraction", validate: "Automated preflight", merge: "Deduplicate and merge", approve: "Expert approval", historyTitle: "Batch history", historyHint: "Review every import and return to its result.", crop: "Crop scope", time: "Imported", status: "Status", action: "Action", view: "View result", pending: "Preflight passed · awaiting review", active: "Approved and active", current: "Active", archived: "Archived", empty: "No batches yet", load: "Loading intake center…", retry: "Retry", success: "Batch processed", failure: "Import failed", enterReview: "Enter expert review", added: "Added records", noReplace: "Current knowledge was not replaced.",
} : {
  knowledge: "知识库", sessions: "研究会话", newSession: "新建育种会话", theme: "色调", back: "育种会话",
  kicker: "KNOWLEDGE INTAKE CENTER", title: "知识库接入中心", lead: "上传一批新的育种资料，系统会自动完成格式检查、去重合并和知识库更新，之后提交专家审核。",
  catalog: "当前活动知识库", healthy: "知识库已就绪", notReady: "尚未建立", latest: "最近更新", preserved: "历史资料已保留，新会话会自动使用完整知识库。", review: "资料审核", noReview: "暂无待审核资料", reviewHint: "上传资料会先自动检查，通过审核后才会进入知识库。",
  uploadKicker: "UPLOAD A BATCH", uploadTitle: "上传知识批次 ZIP", uploadLead: "使用标准批次格式，让每条资料都能被追踪、检查并安全合并。", choose: "选择知识批次文件", drop: "拖入 .zip 文件，或点击浏览", onlyZip: "仅支持 ZIP · 至少包含一类有效资料", preflight: "仅预检，不直接激活", reviewFirst: "上传后先进入专家审核，通过后才会激活", upload: "上传并自动预检", uploading: "处理中…", template: "下载标准 ZIP 模板", demo: "下载谷子示例批次", firstUse: "第一次使用？建议先下载谷子示例批次，完整体验预检、审核和激活流程。", safety: "预检失败或审核未通过时，当前活动知识库不会改变。",
  packageKicker: "PACKAGE CONTENTS", packageTitle: "ZIP 里放什么？", packageLead: "每类资料为育种知识增加不同维度。一次批次可以上传一种或多种资料。", germplasm: "种质资源", graph: "作物知识图谱", evidence: "证据资料", marker: "标记 / QTL", phenotype: "表型协议", trial: "田间试验", formatTitle: "格式和填写规则", format1: "请优先使用下载的标准模板；文献和实验资料整理为 .md 或 .txt 文件。", format2: "暂时没有某类数据时可以不上传，系统会保留现有知识。", format3: "如果 ZIP 中没有任何有效记录，系统会在更新前拒绝该批次。", workflow: "上传之后会发生什么？", safe: "安全解压", validate: "自动预检", merge: "去重合并", approve: "专家审核", historyTitle: "知识批次历史", historyHint: "查看每次导入结果，并返回对应处理页面。", crop: "作物范围", time: "更新时间", status: "状态", action: "操作", view: "查看处理结果", pending: "预检通过 · 待审核", active: "已审核并激活", current: "当前活动", archived: "历史版本", empty: "暂无批次记录", load: "正在加载知识库接入中心…", retry: "重试", success: "批次处理完成", failure: "导入未完成", enterReview: "进入专家审核", added: "新增资料", noReplace: "当前知识库没有被替换。",
});

function toggleLanguage() {
  language.value = language.value === "zh" ? "en" : "zh";
  localStorage.setItem("co-scientist-language", language.value);
}

function selectTheme(value: string | number | Record<string, any> | undefined) {
  if (typeof value !== "string" || !(value in themes)) return;
  themeName.value = value as ThemeName;
  localStorage.setItem("co-scientist-theme", themeName.value);
}

function setFile(file?: File) {
  if (!file) return;
  selectedFile.value = file;
  error.value = "";
  result.value = null;
}

function onFileChange(event: Event) {
  const input = event.target as HTMLInputElement;
  setFile(input.files?.[0]);
}

function onDrop(event: DragEvent) {
  event.preventDefault();
  setFile(event.dataTransfer?.files?.[0]);
}

function formatScope(scope: unknown) {
  return Array.isArray(scope) ? scope.join("、") : String(scope || "—");
}

function formatDate(value: unknown) {
  if (!value) return "—";
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString(isEnglish.value ? "en-GB" : "zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function statusLabel(row: any) {
  if (row?.is_pending) return copy.value.pending;
  if (row?.is_active && row?.approval_status === "approved") return copy.value.active;
  if (row?.is_active) return copy.value.current;
  return copy.value.archived;
}

function statusColor(row: any) {
  if (row?.is_pending) return "orange";
  if (row?.is_active) return "green";
  return "gray";
}

function addedStats() {
  return result.value?.stats?.added || {};
}

async function loadData() {
  loading.value = true;
  error.value = "";
  try {
    const response = await fetch("/api/knowledge/intake");
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    catalog.value = data.catalog || {};
    history.value = data.history || [];
    monitor.value = data.monitor || {};
    directActivationAllowed.value = Boolean(data.direct_activation_allowed);
  } catch {
    error.value = isEnglish.value ? "The intake center could not be loaded." : "知识库接入中心加载失败。";
  } finally {
    loading.value = false;
  }
}

async function submitUpload() {
  if (!selectedFile.value || uploading.value) return;
  uploading.value = true;
  error.value = "";
  result.value = null;
  try {
    const form = new FormData();
    form.append("batch_file", selectedFile.value);
    if (dryRun.value || !directActivationAllowed.value) form.append("dry_run", "true");
    const response = await fetch("/knowledge/upload", { method: "POST", body: form, headers: { Accept: "application/json" } });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    result.value = data.result || null;
    catalog.value = data.catalog || catalog.value;
    history.value = data.history || history.value;
    monitor.value = data.monitor || monitor.value;
    if (result.value?.ok) {
      selectedFile.value = null;
      dryRun.value = false;
      inputKey.value += 1;
    }
  } catch {
    error.value = isEnglish.value ? "The upload request failed. Please try again." : "上传请求失败，请稍后重试。";
  } finally {
    uploading.value = false;
  }
}

onMounted(loadData);
</script>

<template>
  <div class="knowledge-app" :style="themeStyles">
    <a-layout>
      <a-layout-header class="knowledge-topbar">
        <div class="knowledge-topbar-inner">
          <a class="knowledge-brand" href="/"><span class="knowledge-brand-mark">BS</span><span><strong>Breeding Scientist</strong><small>{{ isEnglish ? "Breeding Scientist" : "育种科学家" }}</small></span></a>
          <nav class="knowledge-nav"><a class="active" href="/knowledge">{{ copy.knowledge }}</a><a href="/">{{ copy.sessions }}</a></nav>
          <a-space class="knowledge-actions" :size="10"><a-button type="text" class="knowledge-language" @click="toggleLanguage"><IconTranslate />{{ language === "zh" ? "中文" : "English" }}</a-button><a-dropdown @select="selectTheme"><a-button type="text" class="knowledge-theme"><span class="theme-dot" :style="{ background: currentTheme.color }"></span>{{ copy.theme }} <span>⌄</span></a-button><template #content><a-doption v-for="([key, value]) in Object.entries(themes)" :key="key" :value="key"><span class="theme-option"><i :style="{ background: value.color }"></i>{{ value.label }}<b v-if="themeName === key">✓</b></span></a-doption></template></a-dropdown><a-button type="primary" href="/sessions/new">{{ copy.newSession }}</a-button></a-space>
        </div>
      </a-layout-header>
      <a-layout-content>
        <main class="knowledge-page">
          <div v-if="loading" class="knowledge-loading"><a-spin :size="32" /><p>{{ copy.load }}</p></div>
          <a-result v-else-if="error && !catalog" status="error" :title="error"><template #extra><a-button type="primary" @click="loadData">{{ copy.retry }}</a-button></template></a-result>
          <template v-else>
            <div class="knowledge-breadcrumb"><a href="/">{{ copy.back }}</a><span>/</span><strong>{{ copy.knowledge }}</strong></div>
            <header class="knowledge-hero"><div class="knowledge-kicker"><span></span>{{ copy.kicker }}</div><h1>{{ copy.title }}</h1><p>{{ copy.lead }}</p><div class="knowledge-hero-flow"><span><b>01</b>{{ copy.uploadTitle }}</span><i></i><span><b>02</b>{{ copy.validate }}</span><i></i><span><b>03</b>{{ copy.approve }}</span></div></header>

            <section class="knowledge-status-grid" :class="{ 'single-status': !pendingReviewCount }"><a-card class="knowledge-status-card active-card" :bordered="false"><div class="status-card-top"><span>{{ copy.catalog }}</span><span class="status-orb"><IconCheck /></span></div><div class="status-card-body"><strong>{{ catalog.available ? copy.healthy : copy.notReady }}</strong><p v-if="catalog.available">{{ copy.latest }}：{{ formatDate(catalog.updated_at) }}</p><p v-else>{{ isEnglish ? "Upload the first batch to establish the catalog." : "请先上传第一批育种资料。" }}</p><small v-if="catalog.available">{{ copy.preserved }}</small></div></a-card><a-card v-if="pendingReviewCount" class="knowledge-status-card review-card" :bordered="false"><div class="status-card-top"><span>{{ copy.review }}</span><span class="review-count">{{ pendingReviewCount }}</span></div><strong>{{ `${pendingReviewCount} ${isEnglish ? "batches waiting" : "批资料待审核"}` }}</strong><p>{{ copy.reviewHint }}</p><a href="/knowledge/monitor">{{ isEnglish ? "Enter expert review" : "进入专家审核" }}</a></a-card></section>

            <section class="knowledge-intake-layout"><a-card class="knowledge-upload-panel" :bordered="false"><div class="knowledge-section-heading"><span class="knowledge-step">01</span><div><p class="knowledge-kicker">{{ copy.uploadKicker }}</p><h2>{{ copy.uploadTitle }}</h2></div></div><p class="knowledge-section-lead">{{ copy.uploadLead }}</p><form class="knowledge-upload-form" @submit.prevent="submitUpload"><label class="knowledge-dropzone" @dragover.prevent @drop="onDrop"><input :key="inputKey" type="file" accept=".zip,application/zip" required @change="onFileChange" /><span class="drop-icon"><IconCloud /></span><strong>{{ selectedFile ? selectedFile.name : copy.drop }}</strong><small>{{ selectedFile ? `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB` : copy.onlyZip }}</small><em>{{ copy.choose }}</em></label><label class="knowledge-review-toggle"><input v-model="dryRun" type="checkbox" :disabled="!directActivationAllowed" /><span>{{ directActivationAllowed ? copy.preflight : copy.reviewFirst }}</span></label><div class="knowledge-upload-actions"><a-button html-type="submit" type="primary" :loading="uploading" :disabled="!selectedFile">{{ uploading ? copy.uploading : copy.upload }} <IconUpload /></a-button><a href="/knowledge/template" class="knowledge-outline-button"><IconFile />{{ copy.template }}</a><a href="/knowledge/demo" class="knowledge-outline-button"><IconFile />{{ copy.demo }}</a></div></form><p class="knowledge-demo-note"><strong>{{ copy.firstUse.split("？")[0] }}{{ isEnglish ? "?" : "？" }}</strong>{{ copy.firstUse.includes("？") ? copy.firstUse.split("？").slice(1).join("？") : copy.firstUse }}</p><p class="knowledge-safety-note"><IconCheck /><span>{{ copy.safety }}</span></p></a-card>

              <a-card class="knowledge-package-guide" :bordered="false"><p class="knowledge-kicker">{{ copy.packageKicker }}</p><h2>{{ copy.packageTitle }}</h2><p>{{ copy.packageLead }}</p><ul class="knowledge-source-list"><li><span class="source-format csv">CSV</span><div><strong>{{ copy.germplasm }}</strong><small>{{ isEnglish ? "Material, ID, traits, availability, source" : "材料、ID、性状、可获得性、来源" }}</small></div></li><li><span class="source-format json">JSON</span><div><strong>{{ copy.graph }}</strong><small>{{ isEnglish ? "Traits, genes/QTL, markers, environment and relations" : "材料、性状、基因/QTL、标记、环境和关系" }}</small></div></li><li><span class="source-format text">MD/TXT</span><div><strong>{{ copy.evidence }}</strong><small>{{ isEnglish ? "Literature, experiment notes and expert evidence" : "文献摘要、实验记录、材料确认、专家意见" }}</small></div></li><li><span class="source-format csv">CSV</span><div><strong>{{ copy.marker }}</strong><small>{{ isEnglish ? "Detection method, validation and linked material" : "检测方法、验证状态、关联材料和风险" }}</small></div></li><li><span class="source-format csv">CSV</span><div><strong>{{ copy.phenotype }}</strong><small>{{ isEnglish ? "Measurement method, environment and thresholds" : "测定方法、环境、重复设计和推进阈值" }}</small></div></li><li><span class="source-format csv">CSV</span><div><strong>{{ copy.trial }}</strong><small>{{ isEnglish ? "Environment, material, phenotype, genotype and conclusion" : "环境、材料、表型、基因型和试验结论" }}</small></div></li></ul><div class="knowledge-format-panel"><div class="format-panel-title">{{ copy.formatTitle }}</div><p>{{ copy.format1 }}</p><p>{{ copy.format2 }}</p><p>{{ copy.format3 }}</p></div></a-card></section>

            <section class="knowledge-flow-section"><div class="knowledge-section-heading compact"><span class="knowledge-step">02</span><div><p class="knowledge-kicker">AUTOMATED WORKFLOW</p><h2>{{ copy.workflow }}</h2></div></div><div class="knowledge-flow"><div><span>1</span><strong>{{ copy.safe }}</strong><small>{{ isEnglish ? "Isolated processing" : "隔离处理，不直接触碰活动库" }}</small></div><div><span>2</span><strong>{{ copy.validate }}</strong><small>{{ isEnglish ? "Format and content checks" : "检查文件格式和资料内容" }}</small></div><div><span>3</span><strong>{{ copy.merge }}</strong><small>{{ isEnglish ? "Stable IDs preserve old records" : "按稳定 ID 保留新旧知识" }}</small></div><div><span>4</span><strong>{{ copy.approve }}</strong><small>{{ isEnglish ? "Activation after review" : "通过审核后加入知识库" }}</small></div></div></section>

            <section v-if="result" class="knowledge-result-section"><div class="knowledge-section-heading compact"><span class="knowledge-step">03</span><div><p class="knowledge-kicker">PREFLIGHT RESULT</p><h2>{{ result.ok ? copy.success : copy.failure }}</h2></div></div><a-card class="knowledge-result-panel" :class="result.ok ? 'success' : 'failure'" :bordered="false"><template v-if="result.ok"><div class="result-header"><div><strong>{{ result.dry_run ? copy.pending : copy.active }}</strong><p>{{ copy.noReplace }}</p></div><a-tag :color="result.dry_run ? 'orange' : 'green'">{{ result.dry_run ? copy.pending : copy.active }}</a-tag></div><div class="result-stats"><div><strong>{{ addedStats().germplasm_resources || 0 }}</strong><span>{{ copy.germplasm }}</span></div><div><strong>{{ addedStats().marker_qtl || 0 }}</strong><span>{{ copy.marker }}</span></div><div><strong>{{ addedStats().phenotype_protocol || 0 }}</strong><span>{{ copy.phenotype }}</span></div><div><strong>{{ addedStats().field_trial || 0 }}</strong><span>{{ copy.trial }}</span></div><div><strong>{{ result.stats?.rag_documents_added || 0 }}</strong><span>{{ copy.evidence }}</span></div></div><a v-if="result.dry_run" class="result-review-link" :href="`/knowledge/batches/${result.batch_id}`">{{ copy.enterReview }}</a></template><template v-else><strong>{{ copy.failure }}</strong><p>{{ result.error }}</p><small>{{ copy.noReplace }}</small></template></a-card></section>

            <section class="knowledge-history-section"><div class="knowledge-section-heading compact"><span class="knowledge-step">{{ result ? "04" : "03" }}</span><div><p class="knowledge-kicker">BATCH HISTORY</p><h2>{{ copy.historyTitle }}</h2><p>{{ copy.historyHint }}</p></div></div><div v-if="history.length" class="knowledge-history-table"><div class="history-head"><span>{{ copy.crop }}</span><span>{{ copy.time }}</span><span>{{ copy.status }}</span><span>{{ copy.action }}</span></div><a v-for="row in history" :key="row.batch_id" class="history-row" :href="`/knowledge/batches/${row.batch_id}`"><span class="history-crop-cell"><span class="history-crop-mark">{{ formatScope(row.crop_scope).slice(0, 1).toUpperCase() }}</span><span><strong>{{ formatScope(row.crop_scope) }}</strong><code>{{ row.batch_id }}</code></span></span><span class="history-date" :title="row.imported_at">{{ formatDate(row.imported_at) }}</span><a-tag :color="statusColor(row)">{{ statusLabel(row) }}</a-tag><span class="history-link">{{ copy.view }}</span></a></div><div v-else class="knowledge-empty"><IconFile /><p>{{ copy.empty }}</p></div></section>
          </template>
        </main>
      </a-layout-content>
    </a-layout>
  </div>
</template>

<style scoped>
.knowledge-app { min-height: 100vh; color: #17241f; background: radial-gradient(circle at 7% -4%, color-mix(in srgb, var(--theme-color) 10%, transparent), transparent 32rem), #f7faf8; }.knowledge-topbar { height: 72px; background: rgba(255,255,255,.92); border-bottom: 1px solid #e0e9e2; box-shadow: 0 10px 30px rgba(71,102,83,.05); backdrop-filter: blur(18px); }.knowledge-topbar-inner { max-width: 1440px; height: 100%; margin: auto; padding: 0 28px; display: flex; align-items: center; gap: 38px; }.knowledge-brand { display: flex; align-items: center; gap: 10px; color: #17241f; }.knowledge-brand-mark { display: grid; width: 36px; height: 36px; place-items: center; border-radius: 12px; color: #fff; background: var(--theme-color); box-shadow: 0 8px 20px color-mix(in srgb, var(--theme-color) 25%, transparent); font: 700 12px ui-monospace, monospace; }.knowledge-brand strong,.knowledge-brand small { display: block; }.knowledge-brand strong { font-size: 15px; }.knowledge-brand small { margin-top: 2px; color: #84928a; font-size: 10px; }.knowledge-nav { display: flex; gap: 25px; margin-right: auto; }.knowledge-nav a { position: relative; padding: 25px 0; color: #66746b; font-size: 13px; }.knowledge-nav a.active { color: #17241f; }.knowledge-nav a.active::after { content: ""; position: absolute; right: 0; bottom: 0; left: 0; height: 3px; border-radius: 99px; background: var(--theme-color); }.knowledge-actions :deep(.arco-btn) { height: 38px; border-radius: 999px; transition: transform .25s ease, box-shadow .25s ease, background-color .25s ease; }.knowledge-language,.knowledge-theme { padding: 0 15px !important; border: 1px solid color-mix(in srgb, var(--theme-color) 10%, transparent) !important; color: var(--theme-color) !important; background: color-mix(in srgb, var(--theme-color) 5%, white) !important; box-shadow: 0 8px 22px color-mix(in srgb, var(--theme-color) 9%, transparent); }.knowledge-theme { color: #5f6b63 !important; }.knowledge-language:hover,.knowledge-theme:hover { transform: translateY(-1px); color: var(--theme-color-hover) !important; background: color-mix(in srgb, var(--theme-color) 10%, white) !important; }.knowledge-actions :deep(.arco-btn-primary) { padding: 0 18px; background: var(--theme-color); border-color: var(--theme-color); box-shadow: 0 10px 24px color-mix(in srgb, var(--theme-color) 22%, transparent); }.knowledge-actions :deep(.arco-btn-primary:hover) { transform: translateY(-2px); background: var(--theme-color-hover); border-color: var(--theme-color-hover); box-shadow: 0 14px 30px color-mix(in srgb, var(--theme-color) 30%, transparent); }.theme-dot { display: inline-block; width: 8px; height: 8px; margin-right: 7px; border-radius: 50%; }.theme-option { display: flex; align-items: center; min-width: 108px; gap: 8px; }.theme-option i { width: 9px; height: 9px; border-radius: 50%; }.theme-option b { margin-left: auto; color: var(--theme-color); }
